UPDATE campus_clue
clue_title = #{clueTitle}, clue_content = #{clueContent}, clue_source = #{clueSource}, source_platform = #{sourcePlatform}, original_url = #{originalUrl}, publish_time = #{publishTime}, discover_time = #{discoverTime}, involved_department_id = #{involvedDepartmentId}, involved_account = #{involvedAccount}, keywords = #{keywords}, risk_level = #{riskLevel}, school_relevance_score = #{schoolRelevanceScore}, school_relevance_reason = #{schoolRelevanceReason}, matched_school_terms = #{matchedSchoolTerms}, excluded_reason = #{excludedReason}, topic_category = #{topicCategory}, topic_sub_category = #{topicSubCategory}, topic_reason = #{topicReason}, sentiment = #{sentiment}, language = #{language}, clue_status = #{clueStatus}, duplicate_key = #{duplicateKey}, remark = #{remark}, update_user_id = #{updateUserId}
WHERE clue_id = #{clueId} AND deleted = 0

UPDATE campus_clue
SET clue_status = 'archived',
    remark = #{remark},
    update_user_id = #{updateUserId}
WHERE clue_id = #{clueId}
  AND deleted = 0

UPDATE campus_clue
SET sentiment = #{sentiment},
    update_user_id = #{updateUserId}
WHERE clue_id = #{clueId}
  AND deleted = 0
  AND (clue_status IS NULL OR clue_status != 'archived')

UPDATE campus_clue
SET deleted = 1,
    update_user_id = #{updateUserId}
WHERE clue_id = #{clueId}
  AND deleted = 0

