SELECT 
FROM campus_clue
WHERE deleted = 0
  AND (event_id IS NULL OR event_id != #{eventId})
  AND clue_status != 'archived'

    AND clue_id NOT IN

        #{clueId}



    AND topic_category = #{topicCategory}


    AND risk_level = #{riskLevel}


    AND (
        clue_title LIKE CONCAT('%', #{keyword}, '%')
        OR clue_content LIKE CONCAT('%', #{keyword}, '%')
        OR keywords LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY school_relevance_score DESC, discover_time DESC, id DESC
LIMIT #{limit}

SELECT COUNT(1)
FROM campus_clue
WHERE duplicate_key = #{duplicateKey}
  AND deleted = 0

    AND clue_id != #{excludeClueId}
